mapper.select:
SELECT * FROM TB_DATA_MODEL_CHANGE_HISTORY
WHERE DM_ID = #{dmId}

	AND (APRV_STATUS = 'APPROVED' OR CHANGE_USER_ID = #{currentUserId})


	AND CHANGE_USER_ID = #{changeUserId}


	AND CHANGE_TIER = #{changeTier}


	AND APRV_STATUS = #{aprvStatus}


	AND CHANGE_DT >= #{fromDt}


	AND CHANGE_DT <= #{toDt}

ORDER BY CHANGE_SEQ DESC
LIMIT 500

SELECT SUBMISSION_ID as submissionId, MAX(CHANGE_USER_ID) as changeUserId, MIN(CHANGE_DT) as firstDt, MAX(CHANGE_DT) as lastDt, COUNT(*) as itemCnt, MIN(APRV_STATUS) as oldestStatus, MAX(DM_ID) as dmId FROM TB_DATA_MODEL_CHANGE_HISTORY WHERE SUBMISSION_ID IS NOT NULL AND APRV_STATUS = 'SUBMITTED'
AND CHANGE_USER_ID = #{changeUserId}
GROUP BY SUBMISSION_ID ORDER BY firstDt DESC LIMIT 200

SELECT * FROM TB_DATA_MODEL_CHANGE_HISTORY
WHERE SUBMISSION_ID = #{submissionId}
ORDER BY CHANGE_SEQ ASC

SELECT * FROM TB_DATA_MODEL_CHANGE_HISTORY
WHERE CHANGE_USER_ID = #{currentUserId}
  AND APRV_STATUS = 'DRAFT'

  AND DM_ID = #{dmId}

ORDER BY CHANGE_SEQ ASC

mapper.update:
UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt},
       APRV_COMMENT = #{aprvComment, jdbcType=VARCHAR}
 WHERE CHANGE_SEQ = #{changeSeq}

UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET APRV_STATUS  = 'SUBMITTED',
       SUBMISSION_ID = #{submissionId}
 WHERE CHANGE_USER_ID = #{currentUserId}
   AND APRV_STATUS    = 'DRAFT'
   AND CHANGE_SEQ IN
   #{seq}

UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET DDL_EXEC_DT      = #{ddlExecDt},
       DDL_EXEC_USER_ID = #{ddlExecUserId},
       DDL_EXEC_RESULT  = #{ddlExecResult},
       DDL_EXEC_MESSAGE = #{ddlExecMessage, jdbcType=VARCHAR}
 WHERE CHANGE_SEQ = #{changeSeq}

mapper.delete:
DELETE FROM TB_DATA_MODEL_CHANGE_HISTORY
 WHERE CHANGE_SEQ      = #{changeSeq}
   AND CHANGE_USER_ID  = #{currentUserId}
   AND APRV_STATUS     = 'DRAFT'
